#!/usr/bin/env python3
"""Generate installed module, docs and skill from the single primer source."""

from pathlib import Path

root = Path(__file__).resolve().parents[1]
primer = (root / "primer.md").read_text()
chunks = "\n".join("    " + repr(primer[i : i + 80]) for i in range(0, len(primer), 80))
(root / "chaski_primer.py").write_text(
    '"""Generated by scripts/sync-primer.py; edit primer.md."""\nPRIMER = (\n' + chunks + "\n)\n"
)
(root / "docs/agent-primer.md").write_text(primer)
skill = root / "skills/chaski/SKILL.md"
skill.parent.mkdir(parents=True, exist_ok=True)
skill.write_text(
    "---\nname: chaski\n"
    "description: Read-only Chaski orientation and cursor-state inspection.\n"
    "---\n\n<!-- BEGIN chaski prime -->\n"
    + primer
    + "<!-- END chaski prime -->\n"
)
